with valid as (select id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, level, lower(level) as level_lower, coalesce(level, 'NONE') as resolved_level from employees where hire_date > date '2023-08-06' and manager_id is not null), valid_employees as (select *, case when salary >= 124000 then 'High' when salary >= 49000 then 'Medium' else 'Low' end as salary_band from valid where hire_date between '2023-12-30' and '2024-02-13'), ranked as (select id, manager_id, level_lower, resolved_level, salary_band from (select *, row_number() over (partition by job_title, manager_id order by salary desc, id) as row_num from valid_employees) ranked where row_num = 1), matched_keys as (select manager_id from ranked except distinct select manager_id from employees where is_remote = false), kept_rows as (select s.* from ranked s inner join matched_keys k on s.manager_id = k.manager_id) select manager_id, count(*) as event_count, count(distinct id) as distinct_ids, count(*) as cnt from kept_rows group by cube (manager_id) order by manager_id desc;
